module.exports = async (args) => {
  const errorCount = parseInt(args.variables.user.flowErrorCount) || 0;
  const errorThreshold = parseInt(args.variables.user.flowErrorThreshold) || 0;

  if (errorCount >= errorThreshold) {
    // Threshold exceeded - output 1 (error path)
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 1,
      variables: args.variables,
    };
  } else {
    // Under threshold - output 2 (continue path)
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }
}

