module.exports = async (args) => {
  const fs = require('fs');
  const path = require('path');

  // Get file path from input file object
  const filePath = args.inputFileObj.file;

  // Check if file path exists
  if (!filePath) {
    console.error('Error: File path is undefined or empty');
    args.variables.error = 'File path is undefined or empty';
    args.variables.isHardLinked = false;
    args.variables.hardLinkCount = 0;
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2, // Default to output 2 on error
      variables: args.variables,
    };
  }

  try {
    // Check if file exists
    if (!fs.existsSync(filePath)) {
      console.error(`Error: File does not exist at path: ${filePath}`);
      args.variables.error = `File does not exist at path: ${filePath}`;
      args.variables.isHardLinked = false;
      args.variables.hardLinkCount = 0;
      return {
        outputFileObj: args.inputFileObj,
        outputNumber: 2, // Default to output 2 on error
        variables: args.variables,
      };
    }

    // Get file stats to check hard links
    const stats = fs.statSync(filePath);

    // If nlink > 1, the file has multiple hard links
    const isHardLinked = stats.nlink > 1;

    // Log the result
    console.log(`File: ${path.basename(filePath)}`);
    console.log(`Hard links: ${stats.nlink}`);
    console.log(`Is hard linked: ${isHardLinked}`);

    // Store the result in a variable for later use
    args.variables.isHardLinked = isHardLinked;
    args.variables.hardLinkCount = stats.nlink;
    args.variables.error = null; // No error

    // Route to output 1 if hard linked, output 2 if not
    const outputNumber = isHardLinked ? 1 : 2;

    return {
      outputFileObj: args.inputFileObj,
      outputNumber: outputNumber,
      variables: args.variables,
    };
  } catch (error) {
    // More detailed error handling
    const errorMessage = `Error checking hard links for ${filePath}: ${error.message}`;
    console.error(errorMessage);

    // Set error information in variables
    args.variables.error = errorMessage;
    args.variables.isHardLinked = false;
    args.variables.hardLinkCount = 0;

    // Default to output 2 (not hard linked) in case of error
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }
};

